"""Test-only bounded synthetic SQLite catalog builder.

This helper is never used with customer databases and is not part of any
runtime backup or migration path. It requires the synthetic fixture sentinel.
"""
from __future__ import annotations

from contextlib import closing
from pathlib import Path
import sqlite3


def extend_synthetic_catalog(path: Path, *, target_tables: int) -> str:
    if type(target_tables) is not int or target_tables not in (1000, 1001):
        raise ValueError("SYNTHETIC_CATALOG_LIMIT_ONLY")
    if not isinstance(path, Path) or not path.is_file() or path.is_symlink():
        raise ValueError("SYNTHETIC_FIXTURE_REQUIRED")
    # mode=rw (not r/w create): a missing path must not silently create a DB.
    uri = path.resolve().as_uri() + "?mode=rw"
    with closing(sqlite3.connect(uri, uri=True)) as conn:
        has_fixture = conn.execute(
            "SELECT COUNT(*) FROM events WHERE content = ?",
            ("NOT_FOR_SCHEMA_OUTPUT",)).fetchone()[0]
        if has_fixture != 1:
            raise ValueError("SYNTHETIC_FIXTURE_REQUIRED")
        names = {row[0] for row in conn.execute(
            "SELECT name FROM sqlite_schema "
            "WHERE type='table' AND name NOT GLOB 'sqlite_*'")}
        if len(names) > target_tables:
            raise ValueError("SYNTHETIC_FIXTURE_ALREADY_OVERSIZED")
        last = None
        for i in range(1002):
            if len(names) == target_tables:
                break
            name = f"synthetic_catalog_{i:04d}"
            if name in names:
                continue
            parent = "customers" if i == 0 else f"synthetic_catalog_{i-1:04d}"
            if parent not in names:
                raise ValueError("SYNTHETIC_PARENT_MISSING")
            # Both names are generated by this helper, never untrusted SQL.
            conn.execute(
                f'CREATE TABLE "{name}" ('
                f'"id" INTEGER PRIMARY KEY, '
                f'"parent_id" INTEGER REFERENCES "{parent}"("id"), '
                f'"payload" TEXT)')
            names.add(name)
            last = name
        if len(names) != target_tables:
            raise ValueError("SYNTHETIC_TABLE_BUILD_INCOMPLETE")
        conn.commit()
        if last is None:
            # The caller may request an already-filled synthetic catalog.
            last = sorted(name for name in names
                          if name.startswith("synthetic_catalog_"))[-1]
        return last
